head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > createSubmission]<br/>Submission 을 동적으로 생성합니다. 동일 ID 의 Submission 이 이미 존재하는 경우 기존 Submission 을 삭제 후 재생성합니다.",
    "validation" : [
        "submissionInfo.target(선택) 으로 서버로부터 받은 응답(Response) 데이터를 반영할 DataCollection 의 조건 표현식을 지정할 수 있어야 합니다.",
        "submissionInfo.target 의 action 옵션(append) 으로 기존 데이터 뒤에 응답 데이터를 추가할 수 있어야 합니다.",
        "submissionInfo.target 의 action 옵션(replace) 으로 기존 데이터를 응답 데이터로 교체할 수 있어야 합니다.",
        "submissionInfo.replace='none' 으로 설정하면 Model Instance 에 반영하지 않고 submitDoneHandler 의 이벤트 객체에서 직접 처리할 수 있어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 초기 데이터 설정 (시나리오 1 : append 검증용 1건 / 시나리오 2 : replace 검증용 3건)
scwin.setInitData = function (count) {
    dlt_userList.removeAll();
    for (var i = 0; i < count; i++) {
        var rowIdx = dlt_userList.insertRow(i);
        dlt_userList.setCellData(rowIdx, "id", "INIT_" + (i + 1));
        dlt_userList.setCellData(rowIdx, "name", "초기" + (i + 1));
        dlt_userList.setCellData(rowIdx, "age", "20");
        dlt_userList.setCellData(rowIdx, "dept", "사전등록");
    }
};



scwin.btn_createSubmission_onclick = function () {
    var scenario = par_scenario.getValue();

    // 이전 시나리오에서 남아있을 수 있는 Process Message 정리
    $p.hideProcessMessage();

    if (scenario === "1") {
        // 시나리오 1 : target 조건 표현식 + action='append'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : target + action='append' ──");

        // append 검증용 초기 1건 설정
        scwin.setInitData(1);
        wf_body_bottom.getObj("scwin").setReturnValue("초기 행 수 : " + dlt_userList.getRowCount());

        var submissionInfo = {
            "id" : "sbm_append",
            "action" : "/data/p_createSubmission_userList.json",
            "target" : 'data:json,[{'+'\"id\":\"dlt_userList\",\"action\":\"append\"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitDoneHandler" : function (e) {
                var rowCount = dlt_userList.getRowCount();
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler : append 완료");
                wf_body_bottom.getObj("scwin").setReturnValue("최종 행 수 (초기 1 + 응답 7 = 8) : " + rowCount);
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler : errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_append");
    } else if (scenario === "2") {
        // 시나리오 2 : target 조건 표현식 + action='replace'
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : target + action='replace' ──");

        // replace 검증용 초기 3건 설정
        scwin.setInitData(3);
        wf_body_bottom.getObj("scwin").setReturnValue("초기 행 수 : " + dlt_userList.getRowCount());

        var submissionInfo = {
            "id" : "sbm_replace",
            "action" : "/data/p_createSubmission_userList.json",
            "target" : 'data:json,[{'+'\"id\":\"dlt_userList\",\"action\":\"replace\"}]',
            "method" : "post",
            "mediatype" : "application/json",
            "submitDoneHandler" : function (e) {
                var rowCount = dlt_userList.getRowCount();
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler : replace 완료");
                wf_body_bottom.getObj("scwin").setReturnValue("최종 행 수 (응답 7 으로 교체) : " + rowCount);
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler : errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_replace");
    } else if (scenario === "3") {
        // 시나리오 3 : replace='none' - Model Instance 에 반영하지 않고 콜백에서 직접 처리
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : replace='none' (콜백 직접 처리) ──");

        // 초기 2건 설정 (유지됨을 확인)
        scwin.setInitData(2);
        var beforeCount = dlt_userList.getRowCount();
        wf_body_bottom.getObj("scwin").setReturnValue("초기 행 수 : " + beforeCount);

        var submissionInfo = {
            "id" : "sbm_none",
            "action" : "/data/p_createSubmission_userList.json",
            "method" : "post",
            "mediatype" : "application/json",
            "replace" : "none",
            "submitDoneHandler" : function (e) {
                var afterCount = dlt_userList.getRowCount();
                wf_body_bottom.getObj("scwin").setReturnValue("submitDoneHandler : replace='none' → Model Instance 미반영");
                wf_body_bottom.getObj("scwin").setReturnValue("dlt_userList 행 수 (초기 상태 유지) : " + afterCount);

                // e.responseText 를 수동 파싱하여 처리
                try {
                    var parsed = JSON.parse(e.responseText);
                    var list = parsed.dlt_userList || [];
                    wf_body_bottom.getObj("scwin").setReturnValue("e.responseText 수동 파싱 건수 : " + list.length);
                    if (list.length > 0) {
                        wf_body_bottom.getObj("scwin").setReturnValue("첫 행 id='" + list[0].id + "', name='" + list[0].name + "'");
                    }
                } catch (ex) {
                    wf_body_bottom.getObj("scwin").setReturnValue("responseText 파싱 실패 : " + ex.message);
                }
                $p.hideProcessMessage();
            },
            "submitErrorHandler" : function (e) {
                wf_body_bottom.getObj("scwin").setReturnValue("submitErrorHandler : errorType=" + e.errorType);
                $p.hideProcessMessage();
            }
        };
        $p.createSubmission(submissionInfo);
        $p.executeSubmission("sbm_none");
    }
};
